const I={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',chat:'M21 11a8 8 0 0 1-8 8H7l-5 3V7a5 5 0 0 1 5-5h9a5 5 0 0 1 5 5zM7 8h9M7 12h6',bell:'M5 9a7 7 0 0 1 14 0v7l2 3H3l2-3zM9 22h6',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M3 21v-2a7 7 0 0 1 7-7h4a7 7 0 0 1 7 7v2',back:'m14 5-7 7 7 7',right:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',plus:'M12 4v16M4 12h16',check:'m4 12 5 5L20 6',close:'m5 5 14 14M19 5 5 19',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',filter:'M4 6h16M4 12h16M4 18h16M8 3v6M16 9v6M10 15v6',star:'m12 2 3.1 6.3 6.9 1-5 4.9 1.2 6.8L12 17.8 5.8 21 7 14.2l-5-4.9 6.9-1z',shield:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6zM8 12l3 3 5-6',tool:'M14 5a6 6 0 0 0-7 7L2 17l5 5 5-5a6 6 0 0 0 7-7l-4 4-5-5z',brush:'M8 14 18 2l4 4-12 10M7 14c-4 0-5 4-5 7 4 0 8-1 8-5z',spark:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z',truck:'M2 6h12v12H2zM14 10h4l4 4v4h-8M8 19a2 2 0 1 1-4 0 2 2 0 0 1 4 0M20 19a2 2 0 1 1-4 0 2 2 0 0 1 4 0',book:'M3 3h6l3 3 3-3h6v17h-6l-3 2-3-2H3zM12 6v16',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',brief:'M3 7h18v14H3zM8 7V3h8v4M3 12c5 3 13 3 18 0M10 13h4v4h-4z',heart:'M20 4c-3-3-8 0-8 2 0-2-5-5-8-2-5 5 1 11 8 17 7-6 13-12 8-17z',share:'M12 16V2m-5 5 5-5 5 5M5 12H3v10h18V12h-2',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M12 6v6l4 2',attach:'m8 12 7-7a4 4 0 0 1 6 6L10 22a6 6 0 0 1-8-8L13 3M6 14l9-9',send:'m2 2 20 10L2 22l3-10zM5 12h17',dots:'M5 12h.1M12 12h.1M19 12h.1',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',lock:'M5 10h14v12H5zM8 10V6a4 4 0 0 1 8 0v4M12 15v3',info:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M12 11v6M12 7v.1',phone:'M7 2H4a2 2 0 0 0-2 2c0 10 8 18 18 18a2 2 0 0 0 2-2v-3l-6-2-2 3c-4-1-7-4-8-8l3-2z',camera:'M3 6h4l2-3h6l2 3h4v15H3zM16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',image:'M2 3h20v18H2zM2 16l6-6 5 5 3-3 6 6M16 7h.1',file:'M5 2h9l5 5v15H5zM14 2v6h5M8 13h8M8 17h6',logout:'M10 3H3v18h7M9 12h13m-5-5 5 5-5 5',globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M2 12h20M12 2c-5 6-5 14 0 20 5-6 5-14 0-20',help:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M8 8a4 4 0 1 1 5 4v3M13 18v.1',gift:'M2 8h20v5H2zM4 13v9h16v-9M12 8v14M12 8C2 8 4 0 8 3l4 5c10 0 8-8 4-5z',crown:'m2 6 6 5 4-9 4 9 6-5-3 14H5z',thumb:'M9 10l4-8c4 0 1 8 1 8h6l2 2-3 10H9zM2 10h4v12H2z',flag:'M4 22V2m0 1c6-5 10 5 17 0v11c-7 5-11-5-17 0',trash:'M3 6h18M5 6l1 16h12l1-16M9 6V2h6v4M10 10v8M14 10v8',wifi:'M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0M8 16a6 6 0 0 1 8 0M12 20h.1',retry:'M20 7V2l-4 4a9 9 0 1 0 5 10M20 7h-6',card:'M2 4h20v16H2zM2 9h20M5 16h5',play:'m8 4 12 8-12 8z',edit:'m3 16 13-13 5 5L8 21H3zM13 6l5 5',download:'M12 2v14m-6-6 6 6 6-6M3 17v5h18v-5',face:'M2 8V2h6M16 2h6v6M22 16v6h-6M8 22H2v-6M8 8v3M16 8v3M12 10v4h-2M8 17c2 2 6 2 8 0'};
const icon=(n,c='')=>`<svg class="icon ${c}" viewBox="0 0 24 24" fill="${n==='star'?'#FFD65A':'none'}" stroke="${c.includes('accent')?'#245BDB':n==='star'?'#BD8B14':'#172B4D'}" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${I[n]||I.grid}"/></svg>`;
const go=(r)=>{location.hash=r}; const link=(r,label,cls='')=>`<a href="#${r}" class="${cls}">${label}</a>`; const btn=(label,r,cls='')=>link(r,label,'btn '+cls); const ib=(n,r,label='Назад')=>`<a href="#${r}" class="iconbtn" aria-label="${label}">${icon(n)}</a>`;
const badge=(s,t='')=>`<span class="badge ${t}">${s}</span>`;const avatar=(s='АК',cls='')=>`<div class="avatar ${cls}">${s}</div>`;const rating=(v='4,9',n='32')=>`<span class="rating">${icon('star')}${v} ${n?`<span class="muted" style="font-weight:400">(${n})</span>`:''}</span>`;
const notice=(text,type='info')=>`<div class="notice ${type==='info'?'':type}">${icon(type==='good'?'check':'info')}<div>${text}</div></div>`;
const field=(label,value='',opts={})=>`<div class="field-group"><label class="label">${label}</label><div class="field ${opts.error?'error':''}">${opts.icon?icon(opts.icon):''}${opts.textarea?`<textarea aria-label="${label}">${value}</textarea>`:`<input aria-label="${label}" value="${value}" placeholder="${opts.placeholder||''}" type="${opts.type||'text'}">`}${opts.eye?`<button class="iconbtn" data-action="eye" aria-label="Показать пароль">${icon('eye')}</button>`:''}${opts.arrow?icon('down'):''}</div>${opts.error?`<p class="field-error" role="alert">${opts.error}</p>`:''}</div>`;
const row=(title,sub,n,r,extra='')=>`<a class="list-row" href="#${r}">${icon(n)}<div class="grow"><h3>${title}</h3>${sub?`<p>${sub}</p>`:''}</div>${extra||icon('right','chevron')}</a>`;
const select=(title,sub,selected=true,extra='')=>`<button class="select-row ${selected?'selected':''}" data-action="select">${extra}<div class="grow"><h3 style="font-size:14px">${title}</h3>${sub?`<p class="small muted mt4">${sub}</p>`:''}</div><span class="radio"></span></button>`;
const check=(text,on=true,required=false)=>`<label class="check-row"><input class="native-check" type="checkbox" ${on?'checked':''} ${required?'data-required-consent="true"':''}><span class="check ${on?'on':''}">${icon('check')}</span><span>${text}</span></label>`;
const status=()=>`<div class="status"><span>9:41</span><div class="status-icons"><svg viewBox="0 0 18 12"><path fill="currentColor" d="M0 8h3v4H0zM5 5h3v7H5zM10 2h3v10h-3zM15 0h3v12h-3z"/></svg><svg viewBox="0 0 16 12"><path fill="currentColor" d="M0 3a12 12 0 0 1 16 0L8 12z"/></svg><svg viewBox="0 0 25 12"><rect x="1" y="1" width="20" height="10" rx="2" fill="none" stroke="currentColor"/><rect x="3" y="3" width="16" height="6" rx="1" fill="currentColor"/><path stroke="currentColor" stroke-width="2" d="M24 4v4"/></svg></div></div>`;
const top=(title,back='home',right='')=>`<header class="topbar">${ib('back',back)}<h1>${title}</h1>${right||'<span class="iconbtn"></span>'}</header>`;
const nav=(active='home')=>`<nav class="nav" aria-label="Основная навигация">${[['home','home','Главная'],['catalog','search','Поиск'],['messages','chat','Сообщения'],['notifications','bell','События'],['account','user','Профиль']].map(([r,i,t])=>link(r,icon(i)+t,r===active?'active':'')).join('')}</nav>`;
const shell=(html,opt={})=>`<div class="phone">${status()}${opt.header||''}<main class="scroll ${opt.cls||''}">${html}</main>${opt.bottom|| (opt.nav?nav(opt.nav):'<div class="safety-footer"></div>')}</div>`;
const actions=(label,r,second)=>`<div class="sticky-actions">${second?btn(second[0],second[1],'outline'):''}${btn(label,r)}</div>`;
const title=(h,p='')=>`<h1 class="screen-title">${h}</h1>${p?`<p class="muted small">${p}</p>`:''}`;
const section=(h,all='',r='catalog')=>`<div class="section-title"><h2>${h}</h2>${all?link(r,all):''}</div>`;
const cats=[['tool','Ремонт',''],['spark','Уборка','mint'],['truck','Перевозки','warm'],['brush','Красота','purple'],['book','Обучение','warm'],['grid','Все услуги','']];
const pro=(name='Алексей К.',job='Ремонт и отделка',v='4,9',n='32',price='от 7 500 ₸',promoted=false,initials='АК',cl='')=>`<a class="pro-card" href="#contractor"><div class="row start">${avatar(initials,cl)}<div class="grow"><div class="row between"><h3>${name}</h3>${icon('shield','tiny-icon accent')}</div><p class="small muted mt4">${job}</p><div class="mt4">${rating(v,n)}</div></div></div><p class="description">${name==='Алексей К.'?'Аккуратный ремонт без лишних хлопот. Берусь за небольшие и комплексные задачи.':'Согласуем детали заранее. Работаю со своими инструментами и материалами.'}</p><div class="row between"><span class="price">${price}</span><span class="small muted">Алматы · ≈ 3 км</span></div>${promoted?`<div class="mt12">${badge('Продвигается','warn')} <span class="tiny muted">Платное размещение</span></div>`:''}</a>`;
const order=(name='Собрать кухню и подключить мойку',statusText='Открыт',budget='45 000 ₸',r='order',sub='Бостандыкский район · 14–16 октября')=>`<a class="order-card" href="#${r}"><div class="row between">${badge(statusText,statusText==='В работе'?'good':'')}<span class="tiny muted">№ JB-2048</span></div><h3>${name}</h3><p class="small muted">${sub}</p><div class="row between mt16"><span class="money">${budget}</span><span class="small accent">Подробнее ${icon('right','tiny-icon')}</span></div></a>`;
const routes={}; function route(id,spec,title,render){routes[id]={id,spec,title,render};}
route('home','S06','Главная заказчика',()=>shell(`<div class="homebar"><div class="row between"><a href="#home" class="wordmark">JOBA<span class="dot"></span></a>${link('roles','Заказчик '+icon('down','tiny-icon'),'role')}</div><div class="row between mt8"><a class="location" style="white-space:nowrap" href="#location">${icon('pin','tiny-icon')} Алматы, Казахстан ${icon('down','tiny-icon')}</a><span class="badge neutral">ДЕМО</span></div></div><div class="pad white" style="padding-top:12px"><h1>Хорошие мастера.<br><span class="accent">Ваши задачи.</span></h1>${link('catalog',icon('search')+'<span>Какая услуга нужна?</span>','search mt20')}<div class="categories mt20">${cats.map(([i,t,c])=>link('catalog',`<div class="cat-icon ${c}">${icon(i)}</div>${t}`,'category')).join('')}</div></div><div class="pad" style="padding-top:16px"><div class="hero-card"><div class="hero-art">${icon('brief')}</div><h2>Расскажите о задаче</h2><p>Специалисты сами предложат цену и удобное время</p>${btn('Создать заказ '+icon('plus','tiny-icon'),'create','sm')}</div>${section('Рядом с вами','Все','catalog')}<div class="stack">${pro()}</div></div>`,{nav:'home'}));
route('catalog','S07','Поиск исполнителей',()=>shell(`<div class="pad white" style="padding-top:12px"><div class="row gap8">${link('catalog',icon('search')+'<span>Ремонт и отделка</span>','search grow')}${ib('filter','filters','Фильтры')}</div><div class="chips mt12">${link('location',icon('pin')+'Алматы','chip')}${link('filters','Рейтинг 4,8+','chip blue')}${link('map',icon('pin')+'На карте','chip')}</div></div><div class="pad" style="padding-top:16px"><div class="row between mb16"><span class="small muted">24 специалиста</span>${link('filters','По соответствию '+icon('down','tiny-icon'),'small accent')}</div><div class="stack">${pro('Данияр М.','Мастер по дому','4,9','21','от 6 000 ₸',true,'ДМ','sand')}${pro()}${pro('Николай С.','Сантехника и электрика','4,8','48','от 5 000 ₸',false,'НС','mint')}</div></div>`,{header:top('Специалисты'),nav:'catalog'}));
route('contractor','S08','Профиль исполнителя',()=>shell(`<section class="profile-hero"><div class="profile-cover"></div><div class="row between profile-id">${avatar('АК','big')}${link('report',icon('flag'),'iconbtn fill')}</div><h1>Алексей К.</h1><p class="muted mt4">Ремонт и отделка · Алматы</p><div class="row mt12">${badge(icon('shield','tiny-icon')+'Документ проверен','good')}<span class="tiny muted">12.09.2026</span></div><div class="stats"><div class="stat"><strong>4,9 <span style="color:#BD8B14">★</span></strong><span>32 отзыва</span></div><div class="stat"><strong>38</strong><span>заказов выполнено</span></div><div class="stat"><strong>5 лет</strong><span>опыт со слов мастера</span></div></div><div class="tabs">${link('contractor','Обзор','tab active')}${link('portfolio-project','Портфолио · 6','tab')}${link('reviews','Отзывы','tab')}</div></section><div class="pad" style="padding-top:16px"><h3>Ремонт, которым хочется делиться</h3><p class="small muted mt8">От сборки кухни до обновления квартиры. Обсудим смету, защитим мебель и оставим порядок.</p><div class="row between mt16"><span class="small muted">Стоимость услуг</span><strong>от 7 500 ₸</strong></div>${section('Последние работы','Все 6','portfolio-project')}<div class="portfolio-grid">${link('portfolio-project','<img src="assets/interior.svg" alt="Демонстрационная визуализация светлой гостиной"><h3>Гостиная в тёплых тонах</h3><p>Ремонт · 2026</p>','project')}${link('portfolio-project','<img src="assets/kitchen.svg" alt="Демонстрационная визуализация кухни"><h3>Кухня для семьи</h3><p>Сборка кухни · 2026</p>','project')}</div><p class="tiny muted mt12">Иллюстративные DEMO-проекты</p></div>`,{header:top('Профиль мастера','catalog',ib('share','invite','Поделиться')),bottom:actions('Предложить заказ','invite')}));
route('chat','S25','Чат заказа',()=>shell(`<p class="chat-date">Сегодня, 12 октября</p><div class="bubble">Добрый день! Посмотрел фотографии кухни. Могу приехать в среду к 10:00.<div class="time">09:24</div></div><div class="bubble mine">Здравствуйте! Среда подходит. Инструменты возьмёте с собой?<div class="time">09:26 · Прочитано</div></div><div class="bubble">Да, всё необходимое привезу. Стоимость 45 000 ₸, как в отклике.<div class="time">09:27</div></div><div class="system-note">Вы выбрали Алексея. Условия сохранены в заказе.</div><div class="bubble mine"><img src="assets/kitchen.svg" alt="Демонстрационная схема кухни">Вот схема кухни. До встречи!<div class="time">09:31 · Доставлено</div></div><div class="bubble">Спасибо, до встречи! ${icon('check','tiny-icon')}<div class="time">09:32</div></div>`,{cls:'chat-scroll',header:`<header class="chat-header">${ib('back','messages')}${avatar('АК','sm')}<div class="grow"><h1>Алексей К.</h1><p class="tiny muted">Был в сети 5 минут назад</p></div>${ib('dots','report','Действия')}</header><a class="chat-order" href="#work">${icon('brief')}<div class="grow"><h3 style="font-size:12px">Сборка кухни</h3><p class="tiny muted">№ JB-2048 · В работе · 45 000 ₸</p></div>${icon('right','tiny-icon')}</a>`,bottom:`<form class="composer" id="chat-form"><button type="button" class="iconbtn" data-action="attach" aria-label="Добавить вложение">${icon('plus')}</button><input id="message-input" placeholder="Сообщение" aria-label="Сообщение"><button class="iconbtn send" aria-label="Отправить">${icon('send')}</button></form>`}));
function render(){const r=location.hash.slice(1)||'home';const item=routes[r]||routes.home;document.title='JOBA · '+item.title;document.getElementById('app').innerHTML=item.render();document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{const a=el.dataset.action;if(a==='select'){el.parentElement.querySelectorAll('.select-row').forEach(e=>e.classList.remove('selected'));el.classList.add('selected')}else if(a==='check'){el.classList.toggle('on');el.innerHTML=el.classList.contains('on')?icon('check'):''}else if(a==='eye'){const p=el.parentElement.querySelector('input');p.type=p.type==='password'?'text':'password'}else if(a==='toggle'){el.classList.toggle('off');el.setAttribute('aria-checked',!el.classList.contains('off'))}else if(a==='pin'){const ds=[...document.querySelectorAll('.pin-dots span')];const next=ds.find(x=>!x.classList.contains('on'));if(next)next.classList.add('on');if(ds.every(x=>x.classList.contains('on')))setTimeout(()=>go('home'),180)}else if(a==='pin-back'){const ds=[...document.querySelectorAll('.pin-dots span.on')];ds.pop()?.classList.remove('on')}else if(a==='like'){const was=el.classList.contains('blue');el.parentElement.querySelectorAll('[data-action=like]').forEach(x=>x.classList.remove('blue'));if(!was)el.classList.add('blue');toast('Реакция обновлена в демо')}else toast(el.dataset.message||'Демонстрация: действие без отправки данных')});const accept=document.getElementById('accept-terms');if(accept){const required=[...document.querySelectorAll('[data-required-consent]')];const sync=()=>{accept.disabled=required.length!==2||!required.every(x=>x.checked)};required.forEach(x=>x.addEventListener('change',sync));accept.onclick=()=>{if(!accept.disabled)go('onboarding')};sync();}const form=document.getElementById('chat-form');if(form)form.onsubmit=e=>{e.preventDefault();const inp=document.getElementById('message-input');if(!inp.value.trim())return;const b=document.createElement('div');b.className='bubble mine';b.textContent=inp.value;const t=document.createElement('div');t.className='time';t.textContent='Только в демо · Отправлено';b.appendChild(t);document.querySelector('main').appendChild(b);inp.value='';b.scrollIntoView({behavior:'smooth'})};}function toast(msg){document.querySelector('.toast')?.remove();const d=document.createElement('div');d.className='toast';d.role='status';d.textContent=msg;document.querySelector('.phone').appendChild(d);setTimeout(()=>d.remove(),2800)}window.JOBA={routes};
// MORE_ROUTES
render();

const page=(head,content,opts={})=>shell(`<div class="pad">${content}</div>`,{header:top(head,opts.back||'account',opts.right||''),bottom:opts.action?actions(...opts.action):opts.bottom,nav:opts.nav});
const emptyPage=(head,h,p,i='search',action=['Изменить фильтры','filters'])=>page(head,`<div class="empty"><div class="empty-icon">${icon(i)}</div><h1>${h}</h1><p>${p}</p>${btn(action[0],action[1])}</div>`);
route('welcome','S01','Старт, страна и язык',()=>shell(`<div class="pad"><div class="row between"><span class="wordmark">JOBA<span class="dot"></span></span>${badge('ДЕМО','neutral')}</div><div class="center mt24"><img class="brand-img" src="assets/joba-logo.png" alt="Логотип JOBA"></div><div class="mt24">${title('Дела становятся проще','Находите специалистов и заказы в вашем городе.')}</div><label class="label">Страна услуг</label>${select('Казахстан','KZT · локальные услуги',true,icon('globe'))}${select('Кыргызстан','KGS',false)}<div class="grid2">${select('Россия','RUB',false)}${select('Беларусь','BYN',false)}</div><label class="label">Язык интерфейса</label><a class="field" href="#settings"><span class="grow">Русский</span>${icon('down')}</a><p class="tiny muted mt16">Страна и язык выбираются отдельно. Доступность функций зависит от региона.</p></div>`,{bottom:actions('Продолжить','login')}));
route('login','S02','Вход по номеру и паролю',()=>page('Вход в JOBA',`${title('С возвращением','Войдите в свой аккаунт, чтобы продолжить.')}${field('Номер телефона','',{placeholder:'+7 · номер телефона',type:'tel',icon:'phone'})}${field('Пароль','',{placeholder:'Введите пароль',type:'password',eye:true})}<div class="mt20">${btn('Войти','unlock')}</div>${btn('Нужна помощь со входом?','recovery','ghost')}<div class="hairline"></div><p class="small muted center">Ещё нет аккаунта?</p><div class="mt12">${btn('Зарегистрироваться','register','outline')}</div><div class="notice mt24">${icon('lock')}<div>Ваш номер используется как логин. Подтверждение кодом не требуется.</div></div><div class="mt24 center"><span class="small muted">Казахстан · Русский</span></div>`,{back:'welcome'}));
route('register','S02.register','Создание аккаунта',()=>page('Новый аккаунт',`${title('Добро пожаловать','Один аккаунт для ваших задач и работы.')}${field('Номер телефона','',{placeholder:'+7 · номер телефона',type:'tel',icon:'phone'})}<p class="tiny muted mt8">Номер будет вашим логином, он не подтверждён.</p>${field('Придумайте пароль','',{placeholder:'Не менее 15 символов',type:'password',eye:true})}<p class="tiny muted mt8">Можно использовать пробелы и длинную фразу.</p>${field('Повторите пароль','',{placeholder:'Введите пароль ещё раз',type:'password',eye:true})}${notice('Сохраните пароль в надёжном месте. Он нужен для входа на новом устройстве.')}<div class="mt20">${btn('Продолжить','terms')}</div>${btn('Уже есть аккаунт? Войти','login','ghost')}`,{back:'login'}));
route('terms','S03','Условия и согласия',()=>page('Перед началом',`${title('Понятные правила','Казахстан · Русский · версия от 12.10.2026')}<div class="list mt24">${row('Пользовательское соглашение','Версия KZ-1.1','file','legal')}${row('Политика конфиденциальности','Версия KZ-1.1','shield','legal')}</div><div class="mt24">${check('Принимаю пользовательское соглашение и подтверждаю, что мне исполнилось 18 лет.',false,true)}${check('Ознакомился с политикой конфиденциальности.',false,true)}${check('Хочу получать новости и предложения JOBA. Необязательно.',false)}</div>${notice('Необязательные согласия можно изменить в разделе «Приватность».')}`,{back:'register',bottom:'<div class="sticky-actions"><button class="btn" id="accept-terms" disabled>Принять и продолжить</button></div>'}));
route('onboarding','S04','Первичный профиль',()=>page('Расскажите о себе',`<div class="stepper"><span class="done"></span><span></span><span></span></div><div class="center"><div class="avatar big" style="margin:auto;background:#EAF0FC">${icon('camera')}</div><p class="small accent mt8">Добавить фото</p><p class="tiny muted mt4">Необязательно</p></div>${field('Как к вам обращаться','Марина')}<label class="label">Что вам интересно?</label>${select('Найти специалиста','Разместить заказ или выбрать мастера',true,icon('search'))}${select('Найти заказы','Предлагать услуги и откликаться',false,icon('brief'))}<p class="small muted mt16">Роль можно переключить позже. Для работы исполнителем потребуется проверка документа.</p>`,{back:'terms',action:['Сохранить профиль','pin-setup']}));
route('access','S05','Выбор способа доступа',()=>page('Доступ к JOBA',`${title('Ваши возможности','Поиск, публикации и отклики в одном доступе.')}<div class="card mt20" style="border:2px solid var(--blue)"><div class="row between"><h3>Подписка JOBA</h3>${badge('Обе роли')}</div><div class="big-amount mt16">2 490 ₸ <span class="small muted" style="font-weight:400">/ месяц</span></div><p class="tiny muted mt8">Демонстрационная цена · не предложение</p><div class="hairline"></div><div class="stack gap8"><div class="row small">${icon('check','tiny-icon accent')} Находите исполнителей и заказы</div><div class="row small">${icon('check','tiny-icon accent')} Публикуйте и откликайтесь</div><div class="row small">${icon('check','tiny-icon accent')} Общайтесь по вашим заказам</div></div><div class="mt20">${btn('Посмотреть условия','checkout')}</div><p class="tiny muted mt12">В магазине будет показана актуальная цена. Автопродление можно отменить.</p></div><a href="#reward" class="card row mt12"><div class="cat-icon warm">${icon('play')}</div><div class="grow"><h3 style="font-size:13px">Доступ за рекламу</h3><p class="tiny muted mt4">Демо: 24 часа для заказчика</p></div>${icon('right','tiny-icon')}</a><p class="tiny muted mt12">Рекламный способ доступен только после проверки правил провайдера для страны.</p><div class="row mt16">${btn('Восстановить','restore','ghost')}${btn('Поддержка','support','ghost')}</div>`,{back:'account'}));
route('executor-home','S09','Главная исполнителя',()=>shell(`<div class="homebar"><div class="row between"><span class="wordmark">JOBA<span class="dot"></span></span>${link('roles','Исполнитель '+icon('down','tiny-icon'),'role')}</div><div class="row between mt12"><span class="location">${icon('pin','tiny-icon')} Алматы · в радиусе 10 км</span>${badge('ДЕМО','neutral')}</div></div><div class="pad white" style="padding-top:10px"><div class="row between"><h1>Найдём ваш<br>следующий заказ</h1><div class="avatar sand">АК</div></div><div class="row between mt20"><p class="small muted">Принимаю новые заказы</p><button class="toggle" data-action="toggle" aria-label="Принимать заказы"></button></div></div><div class="pad"><div class="grid2"><a class="metric" href="#work"><strong>2</strong><p>заказа в работе</p></a><a class="metric" href="#invitations"><strong>3</strong><p>новых приглашения</p></a></div>${section('Подходящие заказы','Фильтры','filters')}<div class="chips mb16">${link('executor-home','Для вас','chip active')}${link('executor-home','Ремонт','chip')}${link('top','Топ-100','chip')}</div><div class="stack">${order()}${order('Обновить стены в гостиной','Открыт','до 80 000 ₸','order','Медеуский район · на этой неделе')}</div></div>`,{nav:'home'}));
route('order','S10','Открытый заказ',()=>page('Детали заказа',`<div class="row between">${badge('Открыт')}<span class="tiny muted">№ JB-2048 · 2 часа назад</span></div><h1 class="mt16">Собрать кухню<br>и подключить мойку</h1><div class="row between mt20"><div><p class="small muted">Бюджет заказчика</p><div class="big-amount mt4">45 000 ₸</div></div>${link('report',icon('flag'),'iconbtn fill')}</div><div class="card mt20"><div class="row">${icon('pin','accent')}<div><h3 style="font-size:13px">Алматы, Бостандыкский район</h3><p class="tiny muted mt4">Примерное расположение</p></div></div><div class="hairline"></div><div class="row">${icon('clock','accent')}<div><h3 style="font-size:13px">14–16 октября</h3><p class="tiny muted mt4">Время согласуем · Asia/Almaty</p></div></div></div><h3 class="mt20">Что нужно сделать</h3><p class="small muted mt8">Собрать прямую кухню длиной 2,8 м, установить столешницу и подключить мойку. Мебель уже доставлена. Нужны свои инструменты.</p><img src="assets/kitchen.svg" class="full-photo mt16" style="height:140px;object-fit:cover" alt="Демонстрационный проект кухни"><div class="row mt20">${avatar('МП','sm lilac')}<div class="grow"><h3 style="font-size:13px">Марина П.</h3><p class="tiny muted">Заказчик · 8 завершённых заказов</p></div>${rating('4,9','7')}</div><p class="tiny muted mt16">Стоимость услуги оплачивается по договорённости сторон, вне JOBA.</p>`,{back:'executor-home',action:['Откликнуться','offer']}));
route('account','S11','Мой профиль',()=>shell(`<div class="pad white"><div class="row between"><h1>Мой профиль</h1>${ib('dots','settings','Настройки')}</div><div class="row mt20">${avatar('МП','big lilac')}<div class="grow"><h2>Марина П.</h2><p class="small muted mt4">Алматы · с сентября 2026</p>${link('roles','Заказчик '+icon('down','tiny-icon'),'badge mt8')}</div></div><div class="mt16">${btn('Редактировать профиль','profile-edit','outline')}</div></div><div class="pad"><a class="card row" href="#my-access"><div class="cat-icon">${icon('card')}</div><div class="grow"><h3>Подписка активна</h3><p class="tiny muted mt4">До 12 ноября · управление доступом</p></div>${icon('right','tiny-icon')}</a><div class="list mt16">${row('Мои заказы','2 в работе · 1 открыт','brief','orders')}${row('Мои услуги и портфолио','Настройте профиль исполнителя','tool','services')}${row('Отзывы обо мне','4,9 · 7 отзывов','star','reviews')}${row('Топ-100','Популярные услуги и заказы','crown','top')}${row('Продвижение','Ваши размещения','spark','promotion')}${row('Приглашения и бонусы','Пригласить друга','gift','referrals')}</div><div class="list mt16">${row('Безопасность','PIN, пароль и устройства','lock','security')}${row('Поддержка','Поможем с вашим вопросом','help','support')}${row('Приватность','Ваши данные и согласия','shield','privacy')}${row('Настройки','Язык, страна, уведомления','filter','settings')}</div><p class="demo-note">Демонстрационный профиль. Все данные вымышлены.</p></div>`,{nav:'account'}));
route('services','S12','Редактирование услуг',()=>page('Мои услуги',`${notice('Профиль опубликован. Изменения проходят проверку, текущая версия остаётся видимой.','good')}${field('Заголовок','Ремонт и отделка квартир')}${field('О себе','От сборки кухни до обновления квартиры. Работаю аккуратно, обсуждаю смету заранее.',{textarea:true})}<label class="label">Категории</label><div class="chips">${link('filters','Ремонт ×','chip blue')}${link('filters','Сборка мебели ×','chip blue')}</div><div class="grid2">${field('Цена от','7 500')}${field('Единица','за услугу',{arrow:true})}</div>${field('Зона работы','Алматы · до 10 км',{icon:'pin',arrow:true})}<div class="list mt20">${row('Моё портфолио','6 проектов · 1 на проверке','image','portfolio')}${row('Проверка документа','Документ проверен','shield','verification-status')}</div>`,{action:['Отправить изменения','profile-pending']}));
route('verification','S13','Обязательная проверка документа',()=>page('Проверка исполнителя',`<div class="stepper"><span class="done"></span><span></span><span></span></div>${title('Подтвердите документ','Это нужно, чтобы публиковать услуги, искать заказы и откликаться.')}<div class="notice mt20">${icon('shield')}<div>Документ видят только сотрудники проверки. Он не появится в профиле и переписке.</div></div><label class="label">Документ · Казахстан</label>${select('Удостоверение личности','Лицевая и оборотная сторона',true,icon('card'))}${select('Паспорт','Только страница с данными',false,icon('file'))}<label class="label">Фото документа</label><button class="photo-add" data-action="attach">${icon('camera')}<span>Добавить фотографии<br><span class="tiny muted">В демо файлы не загружаются</span></span></button><p class="tiny muted mt8">Все края видны, текст читается, без бликов.</p>${check('Согласен на обработку документа для проверки личности. '+link('legal','Условия проверки','legal-link'))}<p class="tiny muted">Проверка не гарантирует качество услуги. Заказчик и поддержка доступны без неё.</p>`,{back:'services',action:['Отправить на проверку','verification-status']}));
route('reviews','S14','Отзывы пользователя',()=>page('Отзывы об Алексее',`<div class="row gap8"><div class="big-amount" style="font-size:56px">4,9</div><div class="grow" style="padding-left:15px"><div class="rating">${'★★★★★'.split('').map(()=>icon('star')).join('')}</div><p class="small muted mt8">32 подтверждённых отзыва</p><p class="tiny muted mt4">По завершённым заказам</p></div></div><div class="chips mt24">${link('reviews','Все','chip active')}${link('reviews','С текстом','chip')}${link('reviews','Сначала новые','chip')}</div><div class="stack mt20"><div class="card"><div class="row">${avatar('ЕС','sm sand')}<div class="grow"><h3 style="font-size:13px">Елена С.</h3><p class="tiny muted">Сборка мебели · 8 октября</p></div>${rating('5,0','')}</div><p class="small mt16">Всё аккуратно собрал и убрал после работы. Заранее рассказал, что нужно купить. Рекомендую.</p><div class="mt12">${badge('Заказ завершён','good')}</div></div><div class="card"><div class="row">${avatar('ДА','sm mint')}<div class="grow"><h3 style="font-size:13px">Дмитрий А.</h3><p class="tiny muted">Ремонт комнаты · 2 октября</p></div>${rating('5,0','')}</div><p class="small mt16">Смета и сроки совпали с договорённостью. Отличная работа.</p><div class="mt12">${badge('Заказ завершён','good')}</div></div></div><p class="tiny muted mt16">Реакции в Топ-100 и продвижение не влияют на звёздный рейтинг.</p>`,{back:'contractor'}));
route('security','S15','Безопасность аккаунта',()=>page('Безопасность',`${title('Вы управляете доступом','Один аккаунт, только ваши устройства.')}<div class="list mt24">${row('PIN приложения','Настроен · 6 цифр','lock','pin-setup')}${row('Face ID','Включён на этом iPhone','face','biometric')}${row('Пароль','Изменить пароль аккаунта','lock','password')}${row('Устройства и сессии','2 активных устройства','phone','sessions')}</div><div class="card mt20"><div class="row">${icon('shield','accent')}<h3>Сохранённая сессия</h3></div><p class="small muted mt12">PIN или биометрия открывают приложение только на этом устройстве. Для нового устройства нужен полный вход.</p></div><div class="mt16">${notice('Проверка документа исполнителя выполняется отдельно от PIN и Face ID.')}</div>`,{back:'account'}));
route('create','S16','Создание заказа',()=>page('Новый заказ',`<div class="row between"><span class="small muted">Шаг 1 из 2</span>${badge('Черновик','neutral')}</div><div class="stepper mt12"><span class="done"></span><span></span></div>${title('Что нужно сделать?')}${field('Категория','Сборка мебели',{icon:'tool',arrow:true})}${field('Название','Собрать кухню и подключить мойку')}${field('Опишите задачу','Прямая кухня 2,8 м. Мебель доставлена. Нужны сборка, установка столешницы и подключение мойки.',{textarea:true})}${field('Где нужна услуга','Алматы, Бостандыкский район',{icon:'pin',arrow:true})}<div class="grid2">${field('Срок','14–16 октября',{icon:'clock'})}${field('Бюджет, ₸','45 000')}</div><label class="label">Фотографии задачи</label><button class="photo-add" data-action="attach">${icon('plus')} Добавить фото</button><p class="tiny muted mt12">Точный адрес не будет виден в открытом каталоге.</p>`,{back:'home',action:['Предпросмотр заказа','publish']}));
route('publish','S17','Предпросмотр и публикация',()=>page('Проверить заказ',`<div class="stepper"><span class="done"></span><span class="done"></span></div>${title('Всё верно?','Так вашу задачу увидят исполнители.')}<div class="card mt20"><div class="row between">${badge('Предпросмотр','neutral')}${link('create',icon('edit'),'iconbtn')}</div><h2 class="mt8">Собрать кухню<br>и подключить мойку</h2><p class="small muted mt12">Прямая кухня 2,8 м. Нужны сборка, установка столешницы и подключение мойки.</p><div class="hairline"></div><div class="price-row"><span class="muted">Бюджет</span><strong>45 000 ₸</strong></div><div class="price-row"><span class="muted">Город</span><strong>Алматы</strong></div><div class="price-row"><span class="muted">Когда</span><strong>14–16 октября</strong></div></div><div class="mt20">${notice('Подписка активна. После проверки заказ появится в поиске.','good')}</div><p class="small muted mt16">Цена услуги согласуется с исполнителем. JOBA не принимает оплату за работу.</p>`,{back:'create',action:['Опубликовать заказ','published']}));
route('orders','S18','Мои заказы',()=>shell(`<div class="pad white"><div class="row between"><h1>Мои заказы</h1>${ib('plus','create','Создать заказ')}</div><div class="tabs mt16">${link('orders','Активные · 3','tab active')}${link('completed-orders','Завершённые','tab')}${link('drafts','Черновики','tab')}</div></div><div class="pad stack">${order('Собрать кухню и подключить мойку','В работе','45 000 ₸','work','Алексей К. · 14 октября, 10:00')}${order('Обновить стены в гостиной','Открыт','до 80 000 ₸','offers','4 отклика · выбрать исполнителя')}${order('Установить светильники','В работе','15 000 ₸','work','Николай С. · 16 октября')}</div>`,{nav:'home'}));
route('invite','S19','Пригласить исполнителя',()=>page('Предложить заказ',`<div class="row card">${avatar('АК')}<div><h3>Алексей К.</h3><p class="small muted">Ремонт и отделка</p></div></div><h2 class="mt24">Выберите задачу</h2><p class="small muted mt8">Приглашение не назначает исполнителя. Сначала он подтвердит условия.</p><div class="mt20">${select('Обновить стены в гостиной','до 80 000 ₸ · 17–20 октября',true)}${select('Собрать кухню','45 000 ₸ · 14–16 октября',false)}</div>${field('Сообщение','Здравствуйте! Посмотрите, пожалуйста, мою задачу. Подойдут ли вам сроки?',{textarea:true})}${btn('Создать новый заказ','create','ghost')}`,{back:'contractor',action:['Отправить приглашение','invited']}));
route('invitations','S20','Входящие приглашения',()=>page('Приглашения',`${title('Вас приглашают','3 заказчика предложили вам работу.')}<div class="stack mt20"><div class="card"><div class="row">${avatar('МП','sm lilac')}<div class="grow"><h3 style="font-size:13px">Марина П.</h3><p class="tiny muted">Сегодня в 09:10</p></div>${badge('Новое')}</div><h2 class="mt16" style="font-size:18px">Обновить стены в гостиной</h2><p class="small muted mt8">Бостандыкский район · 17–20 октября</p><h3 class="mt12">до 80 000 ₸</h3><p class="small mt12">«Понравились ваши работы. Сможете помочь с нашей гостиной?»</p><div class="grid2 mt16">${btn('Отказаться','invite-declined','outline')}${btn('Ответить','offer')}</div><p class="tiny muted mt12">Приглашение действует до 15 октября</p></div>${order('Установить полки в кабинете','Приглашение','20 000 ₸','order','Медеуский район · до 18 октября')}</div>`,{back:'executor-home'}));
route('offer','S21','Новый отклик',()=>page('Откликнуться',`<div class="card"><p class="eyebrow">Заказ № JB-2048</p><h3 class="mt8">Собрать кухню и подключить мойку</h3><p class="small muted mt8">Бюджет 45 000 ₸ · 14–16 октября</p></div>${field('Ваше предложение','Здравствуйте! Соберу кухню и подключу мойку. Все инструменты привезу с собой.',{textarea:true})}<div class="grid2">${field('Цена, ₸','45 000')}${field('Когда начнёте','14 октября')}</div>${field('Время и срок работы','10:00 · примерно 5 часов')}<p class="tiny muted mt8">Местное время заказа: Asia/Almaty</p>${field('Отклик действует до','13 октября, 18:00',{arrow:true})}${check('Подтверждаю текущую версию условий заказа.')}<div class="mt16">${notice('Отклик не гарантирует выбор. Договорённость закрепится после подтверждения заказчика.')}</div>`,{back:'order',action:['Отправить отклик','offer-sent']}));
route('offers','S22','Список откликов',()=>page('Отклики · 4',`<div class="card"><h3>Собрать кухню</h3><p class="small muted mt4">№ JB-2048 · 45 000 ₸</p></div><div class="chips mt16 mb16">${link('offers','Все · 4','chip active')}${link('offers','По цене','chip')}${link('offers','По рейтингу','chip')}</div><div class="stack"><div class="card"><div class="row">${avatar('АК')}<div class="grow"><h3>Алексей К.</h3>${rating()}</div>${icon('shield','accent')}</div><h2 class="mt16">45 000 ₸</h2><p class="small muted mt4">14 октября, 10:00 · около 5 часов</p><p class="small mt12">Все инструменты привезу. Есть опыт сборки таких кухонь, примеры в портфолио.</p><div class="grid2 mt16">${btn('Уточнить','chat','outline')}${btn('Выбрать','select-contractor')}</div></div><div class="card"><div class="row">${avatar('ДМ','sand')}<div class="grow"><h3>Данияр М.</h3>${rating('4,9','21')}</div></div><h2 class="mt16">48 000 ₸</h2><p class="small muted mt4">15 октября, 09:00 · 1 день</p><div class="mt16">${btn('Посмотреть отклик','select-contractor','outline')}</div></div></div>`,{back:'orders'}));
route('select-contractor','S23','Подтверждение выбора',()=>page('Подтвердить исполнителя',`${title('Договоримся о главном','После выбора остальные отклики закроются.')}<div class="card mt20"><div class="row">${avatar('АК')}<div><h3>Алексей К.</h3>${rating()}</div></div><div class="hairline"></div><h3>Сборка кухни</h3><div class="price-row"><span class="muted">Стоимость работы</span><strong>45 000 ₸</strong></div><div class="price-row"><span class="muted">Начало</span><strong>14 октября, 10:00</strong></div><div class="price-row"><span class="muted">Длительность</span><strong>Около 5 часов</strong></div><p class="tiny muted mt8">Asia/Almaty · версия заказа 3 · отклика 1</p></div><div class="mt20">${notice('Оплату услуги вы согласуете напрямую с исполнителем. JOBA не хранит и не переводит эти деньги.','warn')}</div>${check('Условия понятны. Подтверждаю выбор Алексея.')}`,{back:'offers',action:['Выбрать Алексея','work']}));
route('work','S24','Рабочий заказ',()=>page('Заказ № JB-2048',`<div class="row between">${badge('В работе','good')}${link('cancel','Отменить','small muted')}</div><h1 class="mt16">Собрать кухню</h1><p class="small muted mt8">Условия согласованы 12 октября</p><div class="card mt20"><div class="row">${avatar('АК')}<div class="grow"><h3>Алексей К.</h3><p class="small muted">Ваш исполнитель</p></div>${link('chat',icon('chat'),'iconbtn fill')}</div><div class="hairline"></div><div class="price-row"><span class="muted">Стоимость работы</span><strong>45 000 ₸</strong></div><div class="price-row"><span class="muted">Начало</span><strong>14 октября, 10:00</strong></div><p class="tiny muted mt8">Время Алматы · расчёт за услугу вне JOBA</p></div><h3 class="mt24">Ход работы</h3><div class="timeline mt20"><div><h3>Исполнитель выбран</h3><p>12 октября, 09:28</p></div><div><h3>Условия согласованы</h3><p>Цена и срок сохранены</p></div><div><h3>Работа началась</h3><p>14 октября, 10:07</p></div><div style="opacity:.5"><h3>Завершение</h3><p>Ожидаем результат от исполнителя</p></div></div><div class="list">${row('Предложить изменение','Цена, срок или состав работ','edit','amendment')}${row('Возникла проблема','Открыть обращение по заказу','help','report')}</div>`,{back:'orders',action:['Открыть чат','chat']}));
route('complete','S26','Принять результат работы',()=>page('Результат работы',`<div class="row between">${badge('Ожидает подтверждения','warn')}<span class="tiny muted">№ JB-2048</span></div><h1 class="mt16">Кухня готова</h1><p class="small muted mt8">Алексей отметил работу выполненной.</p><img class="full-photo mt20" src="assets/kitchen.svg" alt="Демонстрация результата сборки кухни"><div class="card mt16"><div class="row">${avatar('АК','sm')}<div><h3 style="font-size:13px">Сообщение исполнителя</h3><p class="tiny muted">Сегодня в 15:12</p></div></div><p class="small mt12">Всё собрано и подключено, проверил соединения. Фото результата приложил.</p></div><p class="small muted mt16">Проверьте работу перед подтверждением. Если что-то осталось, запросите доработку.</p><div class="mt16">${btn('Нужна доработка','rework','outline')}</div>`,{back:'work',action:['Принять работу','review']}));
