route('review','S28','Оценка после заказа',()=>page('Как всё прошло?',`<div class="center mt12">${avatar('АК','big')}<h2 class="mt16">Работа Алексея</h2><p class="small muted mt4">Сборка кухни · завершено</p></div><div class="stars">${Array(5).fill(icon('star')).join('')}</div><h3 class="center">Отлично!</h3><label class="label">Что особенно понравилось?</label><div class="chips">${link('review','Аккуратность','chip blue')}${link('review','Сроки','chip blue')}${link('review','Общение','chip')}</div>${field('Ваш отзыв','Всё аккуратно и вовремя. Спасибо за работу!',{textarea:true})}<div class="mt20">${notice('Отзыв опубликуется после встречной оценки или окончания окна отзывов. Звёзды доступны только по выполненному заказу.')}</div>`,{back:'complete',action:['Отправить отзыв','review-sent']}));
