route('notifications','S31','Уведомления',()=>shell(`<div class="pad white"><div class="row between"><h1>События</h1>${ib('filter','notification-settings','Настройки уведомлений')}</div><div class="tabs mt16">${link('notifications','Все','tab active')}${link('notifications','Заказы','tab')}${link('notifications','Аккаунт','tab')}</div></div><div class="pad"><p class="eyebrow mb16">Сегодня</p><div class="list">${row('Новый отклик от Алексея','Сборка кухни · 09:24','brief','offers',badge('Новое'))}${row('Работа готова к приёмке','Проверьте результат заказа · 15:12','check','complete')}${row('Поддержка ждёт ответ','Обращение № 1032 · 10:45','chat','support-chat')}</div><p class="eyebrow mt24 mb16">Вчера</p><div class="list">${row('Документ проверен','Теперь доступны функции исполнителя','shield','verification-status')}${row('Ваша подписка активна','Доступ до 12 ноября 2026','card','my-access')}${row('Проект опубликован','Гостиная в тёплых тонах','image','portfolio-project')}</div></div>`,{nav:'notifications'}));
