route('referrals','S37','Приглашения и бонусы',()=>page('Приглашения и бонусы',`<div class="hero-card"><div class="hero-art">${icon('gift')}</div><p class="eyebrow" style="color:#D2DCF0">Вместе удобнее</p><h1 class="mt8" style="font-size:25px">Пригласите друга</h1><p>В демо за выполненные условия — 3 дня доступа обоим.</p></div><div class="card mt20"><p class="small muted">Ваш демонстрационный код</p><div class="row between mt12"><h2 style="letter-spacing:2px">JOBA-DEMO</h2><button class="iconbtn fill" data-action="copy" aria-label="Скопировать код">${icon('file')}</button></div><div class="mt16"><button class="btn" data-action="share">${icon('share')} Поделиться приглашением</button></div></div><h3 class="mt24">Ваш прогресс</h3><div class="card mt12"><div class="row between"><strong>1 приглашение</strong>${badge('Ожидает условия','warn')}</div><p class="small muted mt12">Друг зарегистрировался. Бонус появится после выполнения правил программы.</p></div><div class="list mt16">${row('Как начисляются бонусы','Условия, сроки и ограничения','info','referral-rules')}${row('У меня есть код','Ввести приглашение друга','gift','redeem')}</div><p class="tiny muted mt16">Демонстрационные условия требуют утверждения. Бонус не меняет рейтинг и не выдаётся за само-приглашение.</p>`,{back:'account'}));
route('portfolio','S38','Моё портфолио',()=>page('Моё портфолио',`<div class="row between"><div><h1>Ваши работы</h1><p class="small muted mt8">6 опубликовано · 1 на проверке</p></div>${ib('plus','portfolio-edit','Добавить проект')}</div><div class="chips mt20 mb16">${link('portfolio','Все проекты','chip active')}${link('portfolio','Черновики','chip')}${link('portfolio','Архив','chip')}</div><div class="portfolio-grid">${link('portfolio-edit','<img src="assets/interior.svg" alt="Демо-гостиная"><div class="pad-sm" style="padding:12px"><span class="badge good">Опубликован</span><h3>Гостиная в тёплых тонах</h3><p>Связан с заказом JOBA</p></div>','project')}${link('portfolio-edit','<img src="assets/kitchen.svg" alt="Демо-кухня"><div class="pad-sm" style="padding:12px"><span class="badge warn">На проверке</span><h3>Кухня для семьи</h3><p>Новая версия · 3 фото</p></div>','project')}</div><div class="card mt16"><div class="row">${icon('image','accent')}<div class="grow"><h3>Прихожая в светлых тонах</h3><p class="tiny muted mt4">Черновик · осталось добавить фото</p></div>${ib('edit','portfolio-edit','Редактировать')}</div></div><div class="mt20">${notice('До решения по новой версии посетители видят предыдущую безопасную публикацию.')}</div><div class="mt20">${btn('Изменить порядок проектов','portfolio-order','outline')}</div>`,{back:'services'}));
route('portfolio-project','S39','Просмотр проекта и фотографий',()=>page('Проект портфолио',`<img class="full-photo" style="height:256px;object-fit:cover" src="assets/interior.svg" alt="Демонстрационная светлая гостиная: зелёный диван, тёплое дерево, большие окна"><div class="gallery-dots"><span class="active"></span><span></span><span></span></div><div class="row between"><span class="eyebrow">Ремонт и отделка</span>${link('photo-view','Увеличить','small accent')}</div><h1 class="mt12" style="font-size:25px">Гостиная<br>в тёплых тонах</h1><div class="mt12">${badge(icon('check','tiny-icon')+'Связано с заказом JOBA','good')}</div><p class="small mt16">Обновили отделку стен, уложили покрытие и собрали мебель. Сохранили много света и добавили спокойные природные оттенки.</p><p class="tiny muted mt12">Значок подтверждает связь с завершённым заказом, но не гарантирует качество или авторские права.</p><div class="hairline"></div><div class="row">${avatar('АК','sm')}<div class="grow"><h3 style="font-size:13px">Алексей К.</h3><p class="tiny muted">Автор проекта</p></div>${link('contractor','Профиль','small accent')}</div><p class="tiny muted mt20">DEMO · иллюстративная визуализация</p>`,{back:'contractor',right:ib('flag','report','Пожаловаться')}));
route('support','S40','Встроенная поддержка',()=>page('Поддержка JOBA',`${title('Мы рядом','Расскажите, что случилось. Помощь доступна без подписки.')}<div class="card mt20"><div class="row"><div class="cat-icon">${icon('chat')}</div><div><h3>Написать поддержке</h3><p class="tiny muted mt4">Приватный чат внутри приложения</p></div></div><div class="mt20">${btn('Начать обращение','support-new')}</div></div><div class="list mt16">${row('Мои обращения','2 открытых · 4 решённых','chat','cases')}${row('Проблема с заказом','Условия, отмена и завершение','brief','report')}${row('Доступ и оплата','Подписка, восстановление, награды','card','support-new')}${row('Проверка документа','Статус и исправление данных','shield','verification-status')}${row('Обжаловать решение','Блокировка или модерация','flag','appeal')}</div><div class="mt20">${notice('Не отправляйте пароль и PIN. Для проверки документа используйте специальный защищённый раздел.')}</div>`,{back:'account'}));
route('top','S41','Топ-100 услуг и заказов',()=>page('Топ-100',`<h1>Кого выбирают<br>чаще</h1><p class="small muted mt8">Популярность по реакциям сообщества</p><div class="tabs mt16">${link('top','Услуги','tab active')}${link('top-orders','Заказы','tab')}</div><div class="chips mt16">${link('location','Алматы','chip')}${link('filters','Ремонт','chip')}${link('top','Популярные','chip blue')}</div><a class="card mt16" href="#contractor" style="display:block;background:#FFF9E8;border-color:#F1DFA4"><div class="row between">${badge('Продвигается','warn')}<span class="tiny muted">Платное размещение</span></div><div class="row mt12">${avatar('ДМ','sm sand')}<div class="grow"><h3>Данияр М.</h3><p class="tiny muted">Мастер по дому · от 6 000 ₸</p></div>${icon('right','tiny-icon')}</div></a><div class="row between mt20 mb16"><h3>Органический топ</h3><span class="tiny muted">Обновлён 09:40</span></div><div class="stack">${[['1','АК','Алексей К.','Ремонт и отделка','128','4'],['2','НС','Николай С.','Сантехника и электрика','96','2']].map(([rank,ini,name,job,likes,dis])=>`<div class="card"><div class="row"><strong class="accent" style="font-size:22px;width:18px">${rank}</strong>${avatar(ini,'sm')}<a href="#contractor" class="grow"><h3 style="font-size:14px">${name}</h3><p class="tiny muted">${job}</p></a>${rating('4,9','32')}</div><div class="row mt16"><button data-action="like" class="chip" aria-label="Изменить реакцию">${icon('thumb')} ${likes}</button><button data-action="like" class="chip" aria-label="Изменить реакцию">${icon('thumb','downvote')} ${dis}</button><span class="tiny muted">Реакции к карточке</span></div></div>`).join('')}</div><p class="tiny muted mt16">DEMO: показаны 2 допустимые карточки. Реакции не являются отзывами и не меняют звёздный рейтинг.</p>`,{back:'account'}));
route('promotion','S42','Настройка продвижения',()=>page('Продвинуть объявление',`${title('Больше видимости','Отдельное размещение с отметкой «Продвигается».')}${field('Что продвигаем','Ремонт и отделка · моя услуга',{arrow:true})}${field('Где показывать','Каталог услуг · Алматы · Ремонт',{arrow:true})}<label class="label">Разовый срок</label><div class="chips">${link('promotion','Неделя','chip active')}${link('promotion','Месяц','chip')}${link('promotion','Год','chip')}</div><div class="card mt20"><div class="row between"><span class="small muted">Демонстрационная цена</span><strong style="font-size:23px">1 990 ₸</strong></div><div class="hairline"></div><p class="small">12–19 октября 2026 · Asia/Almaty</p><p class="tiny muted mt8">Без автопродления. Финальная цена и доступность подтверждаются перед покупкой.</p></div><div class="mt16">${notice('Продвижение не добавляет реакции и звёзды. Первое место, показы и заказы не гарантируются.','warn')}</div><div class="list mt16">${row('Условия размещения','Срок, пауза, возврат и раннее закрытие','file','promotion-terms')}${row('Мои продвижения','История и статусы','clock','promotion-history')}</div><p class="tiny muted mt16">Нужны активный доступ и проверенный документ исполнителя.</p>`,{back:'account',action:['Проверить размещение','promotion-checkout']}));
route('messages','S25.inbox','Список переписок',()=>shell(`<div class="pad white"><h1>Сообщения</h1>${link('messages',icon('search')+'<span>Поиск по перепискам</span>','search mt20')}<div class="tabs mt12">${link('messages','Заказы','tab active')}${link('cases','Поддержка','tab')}</div></div><div class="pad"><a href="#chat" class="card row messages-row">${avatar('АК')}<div class="grow"><div class="row between"><h3>Алексей К.</h3><span class="tiny muted">09:32</span></div><p class="tiny accent mt4">Сборка кухни · В работе</p><p class="small muted mt8">Спасибо, до встречи!</p></div><span class="badge">2</span></a><a href="#chat" class="card row mt12 messages-row">${avatar('НС','mint')}<div class="grow"><div class="row between"><h3>Николай С.</h3><span class="tiny muted">Вчера</span></div><p class="tiny accent mt4">Установка светильников</p><p class="small muted mt8">Могу в пятницу после 14:00.</p></div></a><a href="#support-chat" class="card row mt12 messages-row"><div class="cat-icon">${icon('help')}</div><div class="grow"><h3>Поддержка JOBA</h3><p class="small muted mt4">Уточните, пожалуйста, детали...</p></div><span class="badge warn">1</span></a></div>`,{nav:'messages'}));
route('filters','S07.filters','Фильтры поиска',()=>page('Фильтры',`${field('Город','Алматы',{icon:'pin',arrow:true})}<label class="label">Расстояние</label><div class="chips">${link('filters','5 км','chip')}${link('filters','10 км','chip active')}${link('filters','Весь город','chip')}</div><label class="label">Формат услуги</label>${select('С выездом ко мне','Специалист приедет по адресу',true)}${select('У исполнителя','В мастерской или студии',false)}${select('Дистанционно','Город не ограничивает поиск',false)}<label class="label">Стоимость, ₸</label><div class="grid2"><div class="field"><input placeholder="От" aria-label="Цена от"></div><div class="field"><input value="50 000" aria-label="Цена до"></div></div><label class="label">Рейтинг</label><div class="chips">${link('filters','Любой','chip')}${link('filters','4,8 и выше','chip blue')}</div><p class="tiny muted mt12">Рейтинг учитывается вместе с количеством отзывов.</p>${check('Только с проверенным документом')}`,{back:'catalog',action:['Показать 24 специалиста','catalog']}));
