route('pin-setup','S15.pin','Настроить локальный PIN',()=>page('Защитите приложение',`<div class="empty" style="padding-top:16px;padding-bottom:10px"><div class="empty-icon">${icon('lock')}</div><h1>Придумайте PIN</h1><p>6 цифр для быстрого входа на этом устройстве. PIN не отправляется на сервер.</p></div><div class="pin-dots">${'<span class="on"></span>'.repeat(6)}</div><div class="card"><div class="row between"><div><h3>Face ID</h3><p class="tiny muted mt4">Дополнительно к PIN</p></div><button class="toggle" data-action="toggle" aria-label="Включить Face ID"></button></div></div><div class="mt20">${notice('Если безопасная локальная защита недоступна, при открытии потребуется номер и пароль.')}</div><div class="mt20">${btn('Вводить номер и пароль','login','ghost')}</div>`,{back:'security',action:['Подтвердить PIN в демо','home']}));
