route('portfolio-edit','S38.edit','Редактор проекта',()=>page('Редактировать проект',`<div class="row between">${badge('Черновик','neutral')}${link('portfolio','Сохранить','small accent')}</div>${field('Название проекта','Гостиная в тёплых тонах')}${field('Категория','Ремонт и отделка',{arrow:true})}<label class="label">Фотографии · 3 из 10</label><div class="grid2"><a href="#portfolio-photos" style="position:relative"><img src="assets/interior.svg" class="full-photo" alt="Демо-обложка"><span class="badge" style="position:absolute;left:8px;bottom:8px">Обложка</span></a><button class="photo-add" data-action="attach">${icon('plus')} Добавить</button></div>${field('Описание','Обновили отделку стен, уложили покрытие и собрали мебель. Сохранили много света.',{textarea:true})}${field('Связать с заказом','№ JB-1904 · завершён',{arrow:true})}${check('У меня есть права на фотографии и необходимые разрешения.')}<p class="tiny muted">Уберите личные данные, точные адреса и фотографии клиентов без разрешения.</p>`,{back:'portfolio',action:['Отправить на проверку','portfolio-pending']}));
